package com.fitlife.usuario.service;
import com.fitlife.usuario.repository.UsuarioRepository;import com.fitlife.usuario.security.JwtKeyService;import java.nio.file.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;
@Service public class UsuarioService {
 private final UsuarioRepository repo;private final PasswordEncoder encoder;private final JwtKeyService jwt;private final Path uploads;
 public UsuarioService(UsuarioRepository r,PasswordEncoder e,JwtKeyService j,@Value("${fitlife.uploads.directory:./uploads}")String dir){repo=r;encoder=e;jwt=j;uploads=Paths.get(dir).toAbsolutePath().normalize();}
 public Map<String,Object> cadastrar(Map<String,Object>d){String email=str(d,"email"),senha=str(d,"senha"),nome=str(d,"nome"),cpf=str(d,"cpf");if(email.isBlank()||senha.length()<8||nome.isBlank()||cpf.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Informe nome, CPF, e-mail e uma senha com pelo menos 8 caracteres.");if(repo.buscarPorEmail(email)!=null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Já existe uma conta com este e-mail.");try{long id=repo.inserir(d,encoder.encode(senha));return Map.of("id",id,"message","Cadastro realizado com sucesso.");}catch(org.springframework.dao.DuplicateKeyException e){throw new ResponseStatusException(HttpStatus.CONFLICT,"CPF ou e-mail já cadastrado.");}}
 public Map<String,Object> login(Map<String,Object>d){String email=str(d,"email"),senha=str(d,"senha");Map<String,Object> found=repo.buscarPorEmail(email);if(found==null||!encoder.matches(senha,String.valueOf(found.get("senha_hash"))))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"E-mail ou senha inválidos.");long id=((Number)found.get("id")).longValue();Map<String,Object> usuario=repo.buscarPorId(id);return Map.of("accessToken",jwt.emitir(id,email),"tokenType","Bearer","expiresIn",28800,"usuario",usuario);}
 public Map<String,Object> buscar(long id){Map<String,Object> u=repo.buscarPorId(id);if(u==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Usuário não encontrado.");return u;}
 public Map<String,Object> atualizar(long id,Map<String,Object>d){if(repo.buscarPorId(id)==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Usuário não encontrado.");return repo.atualizarPerfil(id,d);}
 public Map<String,Object> atualizarMedico(long id,Map<String,Object>d){if(repo.buscarPorId(id)==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Usuário não encontrado.");return repo.atualizarMedico(id,d);}
 public Map<String,Object> foto(long id,MultipartFile file)throws java.io.IOException{if(repo.buscarPorId(id)==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Usuário não encontrado.");if(file.isEmpty()||file.getSize()>2*1024*1024)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A imagem deve ter até 2 MB.");String type=file.getContentType()==null?"":file.getContentType();if(!List.of("image/jpeg","image/png","image/webp").contains(type))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Envie uma imagem JPEG, PNG ou WebP.");Files.createDirectories(uploads);String ext=switch(type){case "image/jpeg"->"jpg";case "image/png"->"png";case "image/webp"->"webp";default->"img";};String name="usuario-"+id+"-"+UUID.randomUUID()+"."+ext;Files.copy(file.getInputStream(),uploads.resolve(name),StandardCopyOption.REPLACE_EXISTING);String url="/uploads/"+name;repo.atualizarFoto(id,url);return Map.of("fotoUrl",url);}
 private String str(Map<String,Object>m,String k){Object v=m.get(k);return v==null?"":v.toString().trim();}
}
